CREATE OR REPLACE FUNCTION public.get_team_infrastructure_base_cost(p_infrastructure_code text, p_target_level integer)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO ''
AS $function$
declare
  v_costs integer[];
begin
  case p_infrastructure_code
    when 'recruitment_data_room' then v_costs := array[200000, 350000, 550000];
    when 'staff_academy' then v_costs := array[1500000, 2100000, 2900000, 3900000, 5100000];
    when 'training_center' then v_costs := array[100000, 250000, 500000, 900000, 1500000];
    when 'roster_management_center' then v_costs := array[600000, 1100000, 1800000, 2800000, 4200000];
    when 'fan_club_headquarters' then v_costs := array[200000, 450000, 850000, 1400000, 2200000];
    when 'club_shop' then v_costs := array[150000, 350000, 650000, 1050000, 1600000];
    when 'international_youth_center' then v_costs := array[500000, 800000, 1200000, 1700000, 2300000];
    when 'indoor_track' then v_costs := array[180000, 450000, 900000, 1550000, 2400000];
    when 'cryotherapy_center' then v_costs := array[150000, 275000, 450000, 700000, 1000000];
    when 'wind_tunnel' then v_costs := array[400000, 850000, 1500000, 2400000, 3600000];
    when 'weather_center' then v_costs := array[50000, 90000, 150000, 230000, 350000];
    when 'media_center' then v_costs := array[650000, 1200000, 2000000, 3000000, 4300000];
    when 'international_welcome_center' then v_costs := array[800000, 1500000, 2500000, 3800000, 5500000];
    when 'research_lab' then v_costs := array[1200000, 2000000, 3000000, 4200000, 5600000, 7200000, 9000000];
    when 'tactical_center' then v_costs := array[3000000, 3900000, 5100000, 6600000, 8400000];
    else raise exception 'Cette infrastructure d’équipe n’existe pas.';
  end case;

  if p_target_level < 1 or p_target_level > cardinality(v_costs) then
    raise exception 'Niveau d’infrastructure d’équipe invalide.';
  end if;
  return v_costs[p_target_level];
end;
$function$

CREATE OR REPLACE FUNCTION public.get_team_infrastructure_base_duration_days(p_infrastructure_code text, p_target_level integer)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO ''
AS $function$
declare
  v_durations integer[];
begin
  case p_infrastructure_code
    when 'recruitment_data_room' then v_durations := array[7, 14, 21];
    when 'staff_academy' then v_durations := array[10, 16, 22, 28, 35];
    when 'training_center' then v_durations := array[5, 9, 14, 20, 28];
    when 'roster_management_center' then v_durations := array[7, 12, 18, 24, 30];
    when 'fan_club_headquarters' then v_durations := array[6, 10, 15, 21, 28];
    when 'club_shop' then v_durations := array[5, 9, 14, 20, 26];
    when 'international_youth_center' then v_durations := array[10, 16, 22, 28, 35];
    when 'indoor_track' then v_durations := array[7, 11, 16, 22, 28];
    when 'cryotherapy_center' then v_durations := array[6, 10, 15, 21, 28];
    when 'wind_tunnel' then v_durations := array[9, 14, 20, 27, 35];
    when 'weather_center' then v_durations := array[6, 10, 15, 21, 28];
    when 'tactical_center' then v_durations := array[12, 18, 24, 30, 35];
    when 'media_center' then v_durations := array[9, 14, 20, 27, 35];
    when 'international_welcome_center' then v_durations := array[10, 16, 22, 28, 35];
    when 'research_lab' then v_durations := array[10, 15, 20, 25, 30, 33, 35];
    else raise exception 'Cette infrastructure d’équipe n’existe pas.';
  end case;

  if p_target_level < 1 or p_target_level > cardinality(v_durations) then
    raise exception 'Niveau d’infrastructure d’équipe invalide.';
  end if;
  return v_durations[p_target_level];
end;
$function$

CREATE OR REPLACE FUNCTION public.settle_due_infrastructure_projects()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_game_day integer;
  v_project record;
  v_completed integer := 0;
  v_name text;
begin
  perform public.sync_active_season_day();
  select game_year * 28 + current_day_number - 1 into v_game_day
  from public.seasons where status = 'active' limit 1;

  for v_project in
    select * from public.infrastructure_projects
    where status = 'active'
      and infrastructure_code in (
        'indoor_track', 'cryotherapy_center', 'wind_tunnel', 'research_lab',
        'international_welcome_center', 'weather_center', 'tactical_center',
        'roster_management_center', 'media_center'
      )
      and completes_game_day_index <= v_game_day
    order by completes_game_day_index, created_at for update skip locked
  loop
    insert into public.team_infrastructures (
      team_id, infrastructure_code, level, completed_project_id, completed_at, updated_at
    ) values (
      v_project.team_id, v_project.infrastructure_code, v_project.target_level,
      v_project.id, now(), now()
    ) on conflict (team_id, infrastructure_code) do update set
      level = greatest(public.team_infrastructures.level, excluded.level),
      completed_project_id = excluded.completed_project_id,
      completed_at = excluded.completed_at,
      updated_at = now();

    v_name := case v_project.infrastructure_code
      when 'indoor_track' then 'Piste indoor'
      when 'cryotherapy_center' then 'Centre de cryothérapie'
      when 'wind_tunnel' then 'Soufflerie'
      when 'research_lab' then 'Laboratoire R&D'
      when 'international_welcome_center' then 'Centre d’accueil international'
      when 'weather_center' then 'Centre météo'
      when 'tactical_center' then 'Centre tactique'
      when 'roster_management_center' then 'Pôle de gestion sportive'
      else 'Média Center' end;
    insert into public.infrastructure_notifications (team_id, project_id, title, message)
    values (
      v_project.team_id, v_project.id, v_name || ' amélioré',
      v_name || ' atteint désormais le niveau ' || v_project.target_level::text || '.'
    ) on conflict (team_id, project_id) do nothing;
    update public.infrastructure_projects
    set status = 'completed', completed_at = now(), updated_at = now()
    where id = v_project.id;
    v_completed := v_completed + 1;
  end loop;

  return v_completed + public.settle_due_infrastructure_projects_legacy_20260812();
end;
$function$

CREATE OR REPLACE FUNCTION public.start_current_team_infrastructure_project(p_infrastructure_code text, p_country_id uuid DEFAULT NULL::uuid, p_architect_contract_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_context record;
  v_architect_id uuid;
  v_architect_level integer;
  v_project_id uuid;
  v_director_level integer;
  v_required_director_level integer;
  v_current_level integer := 0;
  v_target_level integer;
  v_max_level integer;
  v_base_cost numeric(14, 2);
  v_final_cost numeric(14, 2);
  v_base_duration integer;
  v_final_duration integer;
  v_cost_reduction integer := 0;
  v_duration_reduction integer := 0;
  v_architect_specialty text;
  v_current_game_day integer;
  v_description text;
begin
  if p_infrastructure_code not in (
    'recruitment_data_room',
    'staff_academy',
    'training_center',
    'roster_management_center',
    'fan_club_headquarters',
    'club_shop',
    'international_youth_center',
    'indoor_track',
    'cryotherapy_center',
    'wind_tunnel',
    'research_lab',
    'international_welcome_center',
    'weather_center',
    'tactical_center',
    'media_center'
  ) then
    raise exception 'Cette infrastructure n’existe pas.';
  end if;

  perform public.settle_current_team_finances();
  perform public.settle_due_infrastructure_projects();

  select
    director.id as director_id,
    director.experience_points,
    assignment.team_id,
    season.id as season_id,
    season.game_year,
    season.current_day_number,
    team_season.id as team_season_id,
    team_season.cash_balance,
    season_day.id as season_day_id
  into v_context
  from public.sporting_directors as director
  join public.team_manager_assignments as assignment
    on assignment.sporting_director_id = director.id
   and assignment.role = 'general_manager'
   and assignment.status = 'active'
  join public.seasons as season
    on season.status = 'active'
  join public.team_seasons as team_season
    on team_season.team_id = assignment.team_id
   and team_season.season_id = season.id
  join public.season_days as season_day
    on season_day.season_id = season.id
   and season_day.day_number = season.current_day_number
  where director.auth_user_id = auth.uid()
    and director.status = 'active'
  limit 1;

  if v_context is null then
    raise exception 'Aucune équipe active ne correspond au Directeur Sportif.';
  end if;

  perform 1
  from public.team_seasons
  where id = v_context.team_season_id
  for update;

  if p_infrastructure_code = 'club_shop'
    and not exists (
      select 1
      from public.team_infrastructures
      where team_id = v_context.team_id
        and infrastructure_code = 'fan_club_headquarters'
        and level >= 1
    )
  then
    raise exception 'Construisez d’abord le siège social du Fan Club.';
  end if;

  if p_infrastructure_code = 'international_youth_center' then
    if p_country_id is null or not exists (
      select 1
      from public.countries
      where id = p_country_id
        and is_active
    ) then
      raise exception 'Le pays du centre international est invalide.';
    end if;

    select coalesce(max(center.quality_level), 0)
    into v_current_level
    from public.international_youth_centers as center
    where center.team_id = v_context.team_id
      and center.country_id = p_country_id;
  else
    if p_country_id is not null then
      raise exception 'Cette infrastructure n’est pas liée à un pays.';
    end if;

    select coalesce(max(infrastructure.level), 0)
    into v_current_level
    from public.team_infrastructures as infrastructure
    where infrastructure.team_id = v_context.team_id
      and infrastructure.infrastructure_code = p_infrastructure_code;
  end if;

  v_max_level := case
    when p_infrastructure_code = 'recruitment_data_room' then 3
    when p_infrastructure_code = 'research_lab' then 7
    else 5
  end;

  if v_current_level >= v_max_level then
    raise exception 'Cette infrastructure a déjà atteint son niveau maximal.';
  end if;

  v_target_level := v_current_level + 1;
  v_director_level :=
    public.calculate_staff_director_level(v_context.experience_points);
  v_required_director_level := least(v_target_level, 5) * 10;

  if v_director_level < v_required_director_level then
    raise exception 'Le niveau % de Directeur Sportif est requis pour construire le niveau %.',
      v_required_director_level,
      v_target_level;
  end if;

  perform public.assert_team_infrastructure_construction_slot(
    v_context.team_id,
    p_infrastructure_code,
    p_country_id,
    p_architect_contract_id
  );

  case p_infrastructure_code
    when 'recruitment_data_room' then
      v_base_cost := 200000;
      v_base_duration := (array[14, 28, 42]::integer[])[v_target_level];
      v_description := 'Construction Data Room';
    when 'staff_academy' then
      v_base_cost := 1500000;
      v_base_duration := (array[42, 49, 56, 70, 84]::integer[])[v_target_level];
      v_description := 'Académie des métiers';
    when 'training_center' then
      v_base_cost := 100000;
      v_base_duration := (array[7, 14, 24, 35, 49]::integer[])[v_target_level];
      v_description := 'Centre d’entraînement';
    when 'roster_management_center' then
      v_base_cost := 600000;
      v_base_duration := (array[7,12,18,24,30]::integer[])[v_target_level];
      v_description := 'Pôle de gestion sportive';
    when 'fan_club_headquarters' then
      v_base_cost := 200000;
      v_base_duration := (array[10, 18, 28, 40, 56]::integer[])[v_target_level];
      v_description := 'Siège social du Fan Club';
    when 'club_shop' then
      v_base_cost := 150000;
      v_base_duration := (array[8, 16, 24, 34, 46]::integer[])[v_target_level];
      v_description := 'Boutique du club';
    when 'international_youth_center' then
      v_base_cost := 500000;
      v_base_duration := (array[28, 35, 42, 49, 56]::integer[])[v_target_level];
      v_description := 'Centre international';
    when 'indoor_track' then
      v_base_cost := 180000;
      v_base_duration := (array[10, 18, 28, 40, 55]::integer[])[v_target_level];
      v_description := 'Piste indoor';
    when 'cryotherapy_center' then
      v_base_cost := 250000;
      v_base_duration := (array[12, 22, 34, 48, 64]::integer[])[v_target_level];
      v_description := 'Centre de cryothérapie';
    when 'wind_tunnel' then
      v_base_cost := 400000;
      v_base_duration := (array[16, 28, 42, 58, 76]::integer[])[v_target_level];
      v_description := 'Soufflerie';
    when 'weather_center' then
      v_base_cost := 500000;
      v_base_duration := (array[14, 24, 36, 50, 66]::integer[])[v_target_level];
      v_description := 'Centre météo';
    when 'tactical_center' then
      v_base_cost := 3000000;
      v_base_duration := (array[12,18,24,30,35]::integer[])[v_target_level];
      v_description := 'Centre tactique';
    when 'media_center' then
      v_base_cost := 650000;
      v_base_duration := (array[18, 30, 44, 60, 78]::integer[])[v_target_level];
      v_description := 'Média Center';
    when 'international_welcome_center' then
      v_base_cost := 800000;
      v_base_duration := (array[24, 38, 54, 72, 84]::integer[])[v_target_level];
      v_description := 'Centre d’accueil international';
    else
      v_base_cost := 1200000;
      v_base_duration := (array[28, 42, 56, 70, 84, 84, 84]::integer[])[v_target_level];
      v_description := 'Laboratoire R&D';
  end case;

  v_base_duration := public.get_team_infrastructure_base_duration_days(
    p_infrastructure_code,
    v_target_level
  );

  v_base_cost := round(
    v_base_cost * case v_target_level
      when 1 then 1.0
      when 2 then 0.6
      when 3 then 0.7
      when 4 then 0.8
      else 0.9
    end
  );

  v_base_cost := public.get_team_infrastructure_base_cost(
    p_infrastructure_code,
    v_target_level
  );

  if p_architect_contract_id is not null then
    select
      contract.id,
      member.level,
      coalesce(member.architect_specialty, 'balanced') as specialty
    into v_architect_id, v_architect_level, v_architect_specialty
    from public.staff_contracts as contract
    join public.staff_members as member
      on member.id = contract.staff_member_id
    where contract.id = p_architect_contract_id
      and contract.team_id = v_context.team_id
      and contract.status = 'active'
      and member.role = 'architect';

    if v_architect_id is null then
      raise exception 'Cet architecte ne fait pas partie du staff actif de votre équipe.';
    end if;

    if v_architect_specialty = 'economist' then
      v_cost_reduction := v_architect_level * 6;
      v_duration_reduction := v_architect_level * 2;
    elsif v_architect_specialty = 'foreman' then
      v_cost_reduction := v_architect_level * 2;
      v_duration_reduction := v_architect_level * 6;
    else
      v_cost_reduction := v_architect_level * 4;
      v_duration_reduction := v_architect_level * 4;
    end if;
  end if;

  v_cost_reduction := public.get_architect_adjusted_reduction(
    p_architect_contract_id,
    v_cost_reduction,
    'cost'
  );
  v_duration_reduction := public.get_architect_adjusted_reduction(
    p_architect_contract_id,
    v_duration_reduction,
    'duration'
  );
  v_final_cost := round(v_base_cost * (1 - v_cost_reduction / 100.0));
  v_final_duration := greatest(
    1,
    ceil(v_base_duration * (1 - v_duration_reduction / 100.0))::integer
  );

  if v_context.cash_balance < v_final_cost then
    raise exception 'Trésorerie insuffisante pour lancer ce chantier.';
  end if;

  v_current_game_day :=
    v_context.game_year * 28 + v_context.current_day_number - 1;

  insert into public.infrastructure_projects (
    team_id,
    infrastructure_code,
    country_id,
    target_level,
    architect_contract_id,
    architect_specialty,
    architect_level,
    base_cost,
    final_cost,
    base_duration_days,
    final_duration_days,
    cost_reduction_percentage,
    duration_reduction_percentage,
    started_season_id,
    started_day_number,
    starts_game_day_index,
    completes_game_day_index
  ) values (
    v_context.team_id,
    p_infrastructure_code,
    p_country_id,
    v_target_level,
    p_architect_contract_id,
    case when p_architect_contract_id is null then null else v_architect_specialty end,
    case when p_architect_contract_id is null then null else v_architect_level end,
    v_base_cost,
    v_final_cost,
    v_base_duration,
    v_final_duration,
    v_cost_reduction,
    v_duration_reduction,
    v_context.season_id,
    v_context.current_day_number,
    v_current_game_day,
    v_current_game_day + v_final_duration
  )
  returning id into v_project_id;

  insert into public.team_finance_transactions (
    team_season_id,
    season_day_id,
    day_number,
    amount,
    category,
    status,
    description,
    source_reference,
    posted_at
  ) values (
    v_context.team_season_id,
    v_context.season_day_id,
    v_context.current_day_number,
    -v_final_cost,
    'building',
    'posted',
    v_description || ' — niveau ' || v_target_level::text,
    'infrastructure-project:' || v_project_id::text,
    now()
  );

  update public.team_seasons
  set cash_balance = cash_balance - v_final_cost
  where id = v_context.team_season_id;

  return v_project_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.start_current_team_rider_performance_preparation(p_rider_id uuid, p_preparation_type text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET lock_timeout TO '3s'
AS $function$
declare
  v_context record;
  v_policy record;
  v_level integer;
  v_game_day integer;
  v_bonus_start integer;
  v_bonus_end integer;
  v_bonus numeric;
  v_occupied integer;
  v_camp uuid;
  v_id uuid;
begin
  if auth.uid() is null then
    raise exception 'Authentification requise.';
  end if;
  if p_rider_id is null or p_preparation_type is null
    or p_preparation_type not in ('indoor_track', 'wind_tunnel')
  then
    raise exception 'Type de préparation invalide.';
  end if;

  perform public.sync_active_season_day();
  select
    assignment.team_id,
    season.id as season_id,
    season.game_year,
    season.current_day_number,
    team_season.id as team_season_id
  into v_context
  from public.sporting_directors as director
  join public.team_manager_assignments as assignment
    on assignment.sporting_director_id = director.id
   and assignment.role = 'general_manager'
   and assignment.status = 'active'
  join public.seasons as season on season.status = 'active'
  join public.team_seasons as team_season
    on team_season.team_id = assignment.team_id
   and team_season.season_id = season.id
  where director.auth_user_id = auth.uid()
    and director.status = 'active'
  limit 1;
  if not found then
    raise exception 'Aucune équipe active.';
  end if;
  if v_context.current_day_number > 26 then
    raise exception 'Cette préparation de deux jours doit commencer avant la fin de la saison.';
  end if;
  v_game_day := v_context.game_year * 28 + v_context.current_day_number - 1;

  -- Free only this team's due slots. Do not settle every team's preparations
  -- when one sporting director submits a request.
  update public.rider_performance_preparations as preparation
  set status = 'completed'
  where preparation.team_id = v_context.team_id
    and preparation.status = 'planned'
    and preparation.preparation_end_game_day < v_game_day;

  -- Always acquire rider then facility. The rider lock prevents simultaneous
  -- indoor/wind-tunnel camps; the facility lock serializes its capacity check.
  perform 1
  from public.riders as rider
  where rider.id = p_rider_id
    and exists (
      select 1 from public.rider_contracts as contract
      where contract.rider_id = rider.id
        and contract.team_id = v_context.team_id
        and contract.status = 'active'
    )
  for update;
  if not found or not exists (
    select 1
    from public.rider_contracts as contract
    where contract.rider_id = p_rider_id
      and contract.team_id = v_context.team_id
      and contract.status = 'active'
  ) then
    raise exception 'Ce coureur n’appartient pas à votre équipe.';
  end if;

  select infrastructure.level
  into v_level
  from public.team_infrastructures as infrastructure
  where infrastructure.team_id = v_context.team_id
    and infrastructure.infrastructure_code = p_preparation_type
  for update;
  if not found or v_level < 1 then
    if p_preparation_type = 'indoor_track' then
      raise exception 'Construisez d’abord la Piste indoor.';
    else
      raise exception 'Construisez d’abord la Soufflerie.';
    end if;
  end if;

  select policy.rating_bonus, policy.bonus_days, policy.capacity
  into v_policy
  from public.get_performance_preparation_policy(v_level) as policy;
  if not found then
    raise exception 'Niveau d’installation invalide.';
  end if;
  v_bonus := least(3.3, greatest(1, round(
    v_policy.rating_bonus
      * public.get_team_infrastructure_efficiency_multiplier(
        v_context.team_id,
        p_preparation_type
      ),
    2
  )));
  v_bonus_start := v_game_day + 3;
  v_bonus_end := v_game_day + 2 + v_policy.bonus_days;

  if exists (
    select 1 from public.rider_injuries as injury
    where injury.rider_id = p_rider_id and injury.status <> 'recovered'
  ) then
    raise exception 'Ce coureur est actuellement blessé.';
  end if;
  if exists (
    select 1 from public.rider_form_camps as camp
    where camp.rider_id = p_rider_id
      and camp.season_id = v_context.season_id
      and camp.status <> 'cancelled'
      and camp.start_day_number <= v_context.current_day_number + 2
      and camp.end_day_number >= v_context.current_day_number + 1
  ) then
    raise exception 'Ce coureur est déjà indisponible pendant cette période.';
  end if;
  if exists (
    select 1
    from public.race_rosters as roster
    join public.race_registrations as registration
      on registration.id = roster.race_registration_id
     and registration.status in ('pending', 'accepted')
    join public.stages as stage
      on stage.race_edition_id = registration.race_edition_id
     and stage.status <> 'cancelled'
    join public.season_days as day on day.id = stage.season_day_id
    where roster.rider_id = p_rider_id
      and roster.status in ('selected', 'confirmed')
      and day.season_id = v_context.season_id
      and day.day_number between v_context.current_day_number + 1
        and v_context.current_day_number + 2
  ) then
    raise exception 'Ce coureur est engagé en course pendant cette préparation.';
  end if;

  -- A transfer must not allow stacking two bonuses of the same type. Distinct
  -- types may still coexist once their preparation camps no longer overlap.
  if exists (
    select 1 from public.rider_performance_preparations as preparation
    where preparation.rider_id = p_rider_id
      and preparation.preparation_type = p_preparation_type
      and preparation.status <> 'cancelled'
      and preparation.bonus_start_game_day <= v_bonus_end
      and preparation.bonus_end_game_day >= v_bonus_start
  ) then
    raise exception 'Ce coureur bénéficie déjà d’une préparation de ce type sur cette période.';
  end if;

  select count(*)::integer
  into v_occupied
  from public.rider_performance_preparations as preparation
  where preparation.team_id = v_context.team_id
    and preparation.preparation_type = p_preparation_type
    and preparation.status = 'planned';
  if v_occupied >= v_policy.capacity then
    raise exception 'Toutes les places de cette installation sont occupées (%/%).',
      v_occupied, v_policy.capacity;
  end if;

  insert into public.rider_form_camps (
    rider_id, team_season_id, season_id, camp_type,
    start_day_number, end_day_number, form_gain_per_day, price_per_day, total_price
  ) values (
    p_rider_id, v_context.team_season_id, v_context.season_id,
    case when p_preparation_type = 'indoor_track'
      then 'indoor_preparation' else 'wind_tunnel_preparation' end,
    v_context.current_day_number + 1, v_context.current_day_number + 2, 0, 0, 0
  ) returning id into v_camp;

  insert into public.rider_performance_preparations (
    team_id, team_season_id, season_id, rider_id, form_camp_id,
    preparation_type, building_level, preparation_start_game_day,
    preparation_end_game_day, bonus_start_game_day, bonus_end_game_day, rating_bonus
  ) values (
    v_context.team_id, v_context.team_season_id, v_context.season_id,
    p_rider_id, v_camp, p_preparation_type, v_level,
    v_game_day + 1, v_game_day + 2, v_bonus_start, v_bonus_end, v_bonus
  ) returning id into v_id;
  return v_id;
end;
$function$
